-- Reserve new level-60 Naxxramas item IDs. The original Wrath templates remain available.
-- Item stats use installed Epic property points, with armor, block and weapon DPS
-- benchmarked against adjacent level-60 raid gear. Preserve socket colors and weapon speed.
START TRANSACTION;

CREATE TEMPORARY TABLE `_coa_naxx_gear_budget` (
    `original` INT UNSIGNED NOT NULL, `variant` INT UNSIGNED PRIMARY KEY,
    `ItemLevel` INT UNSIGNED NOT NULL, `stat_value1` INT NOT NULL, `stat_value2` INT NOT NULL, `stat_value3` INT NOT
    NULL, `stat_value4` INT NOT NULL, `stat_value5` INT NOT NULL, `stat_value6` INT NOT NULL, `stat_value7` INT NOT
    NULL, `stat_value8` INT NOT NULL, `stat_value9` INT NOT NULL, `stat_value10` INT NOT NULL, `armor` INT UNSIGNED
    NOT NULL, `block` INT UNSIGNED NOT NULL, `holy_res` INT NOT NULL, `fire_res` INT NOT NULL, `nature_res` INT NOT
    NULL, `frost_res` INT NOT NULL, `shadow_res` INT NOT NULL, `arcane_res` INT NOT NULL, `dmg_min1` DECIMAL(12,3)
    NOT NULL, `dmg_max1` DECIMAL(12,3) NOT NULL, `dmg_min2` DECIMAL(12,3) NOT NULL, `dmg_max2` DECIMAL(12,3) NOT
    NULL, `socketBonus` INT UNSIGNED NOT NULL
) ENGINE=InnoDB;

DELETE FROM `_coa_naxx_gear_budget`;

