    `wrath`.`VerifiedBuild`
FROM `_coa_naxx_gear_budget` AS `budget`
JOIN `item_template` AS `wrath` ON `wrath`.`entry` = `budget`.`original`
ON DUPLICATE KEY UPDATE
    `RequiredLevel` = VALUES(`RequiredLevel`), `ItemLevel` = VALUES(`ItemLevel`), `stat_value1` =
    VALUES(`stat_value1`), `stat_value2` = VALUES(`stat_value2`), `stat_value3` = VALUES(`stat_value3`),
    `stat_value4` = VALUES(`stat_value4`), `stat_value5` = VALUES(`stat_value5`), `stat_value6` =
    VALUES(`stat_value6`), `stat_value7` = VALUES(`stat_value7`), `stat_value8` = VALUES(`stat_value8`),
    `stat_value9` = VALUES(`stat_value9`), `stat_value10` = VALUES(`stat_value10`), `armor` = VALUES(`armor`),
    `block` = VALUES(`block`), `holy_res` = VALUES(`holy_res`), `fire_res` = VALUES(`fire_res`), `nature_res` =
    VALUES(`nature_res`), `frost_res` = VALUES(`frost_res`), `shadow_res` = VALUES(`shadow_res`), `arcane_res` =
    VALUES(`arcane_res`), `dmg_min1` = VALUES(`dmg_min1`), `dmg_max1` = VALUES(`dmg_max1`), `dmg_min2` =
    VALUES(`dmg_min2`), `dmg_max2` = VALUES(`dmg_max2`), `socketBonus` = VALUES(`socketBonus`);

DELETE FROM `item_dbc` WHERE `ID` IN (SELECT `variant` FROM `_coa_naxx_gear_budget`);
     `InventoryType`, `SheatheType`)
SELECT `gear`.`entry`, `gear`.`class`, `gear`.`subclass`, `gear`.`SoundOverrideSubclass`, `gear`.`Material`,
    `gear`.`displayid`, `gear`.`InventoryType`, `gear`.`sheath`
FROM `_coa_naxx_gear_budget` AS `budget`
JOIN `item_template` AS `gear` ON `gear`.`entry` = `budget`.`variant`;

DROP TEMPORARY TABLE `_coa_naxx_gear_budget`;

